const addNode = () => {
    decomposeSeqRef.current++; // 手动加卡 = 放弃在途拆解结果（OCR r1 medium）
    setRegenArmed(false); // 手动加卡 = 放弃当前已 arm 的重新生成意图（与 openWorkflow/createBlank 一致）

// 先快照原始 title，循环里 base 必须用原值（iter_mut 改写 st.title 后下
// 一轮读到的就是带后缀的值，会让 "审阅"/"审阅"/"审阅" 撞出 "审阅（2）（2）"
// 而不是期望的 "审阅（3）"，并使 validate_suffixes_duplicate_titles 红）
let originals: Vec<String> = subtasks.iter().map(|s| s.title.clone()).collect();
let mut used: std::collections::HashSet<String> = std::collections::HashSet::new();
for (i, st) in subtasks.iter_mut().enumerate() {
    if used.insert(originals[i].clone()) {
        continue;
    }
    let base = originals[i].clone();
    let mut n = 2usize;
    while !used.insert(format!("{base}（{n}）")) {
        n += 1;
    }
    st.title = format!("{base}（{n}）");
}

